import json,pathlib,hashlib,html,os,re
R=pathlib.Path.cwd(); O=R/'docs/requirements-confirmation/phase1-spec/tasks/yellow-dispatch-gates-20261103'; T=O.parent
p=json.loads((O/'audit.json').read_text(encoding='utf-8'))
for r in p['actions']:
 if r['module']=='M04': r['authorized_preparation']='s2-exact-design full packet already exists. No NEW uncovered original-scope preparation established by this audit; do not dispatch duplicate packet/coverage wrapper. G1-G4 review is scoped only, not full module acceptance.'
p['next_dispatch']={'id':'OWNER-EXACT-CANDIDATE-DISPOSITION','mode':'OWNER_DECISION_REQUIRED_FOR_NEW_PRODUCT_SEAMS','action':'Select one existing exact candidate below: adopt specified hash and architecture/contracts/BDD/envelope implications, return specific corrections, or defer. This is not reapproval of standing implementation authorization.','smallest_decision':'M01 CR-D1..D3 existing closed candidate: choose native provider/issuer lifecycle, durable Ready lookup/restart, and explicit closed publish admission as one coherent revision. Without its prerequisite provider design no product Skeleton dispatch. Other module decisions remain independent.','candidate':p['actions'][0]['candidate'],'sha256':p['actions'][0]['candidate_sha256'],'decision_detail':'docs/requirements-confirmation/phase1-spec/tasks/M01/planning/copy-ready-correction/owner-decisions.json','accepted_document_review':p['actions'][0]['review'],'developer':'separate implementation agent after approved exact file envelope + Skeleton/intended RED + independent stage acceptance','verifier':'separately launched read-only verifier, never implementation author','next_after_adoption':'Coordinator dispatches only exact approved slice Skeleton/RED; standing automatic implementation applies after that gate. Do not implement fixture oracle as native provider.'}
p['gray_fallback']={'inspected':['PD-P1-M08-VERIFY-01','PD-P1-F03-DELIVERY-01'],'M08':'Original VERIFY permits isolated native evidence only; dependencies module deliveries and exact versioned portable artifact unmet. Accepted PREP must not reopen. PD1-PD3 harness architecture adoption remains separate; Windows11/native cannot be fabricated.','F03':'Original packet explicitly limits current writes to planning/evidence; PREP+G01+G04 exact architecture and valid RED prerequisites missing. Source/test implementation not dispatched from Gray color.','conclusion':'No fresh approved product slice or demonstrably NEW nonduplicate preparation established in these inspected candidates. This bounded audit does not claim every Gray/Red action blocked. Continue dispatch selection if Owner decision cannot be obtained; do not loop passed probes.'}
p['source_proof']=[{'path':'apps/sgenaxis-desktop/crates/sgenaxis-ports/src/file_commit.rs','line':58,'fact':'FileCommitPort is existing port seam; new durable native proof authority is not supplied by document fixture membership.'}]
for q in [T/'PD-P1-M08-VERIFY-01.json',T/'PD-P1-F03-DELIVERY-01.json',T/'M08/planning/current-state.json',R/'apps/sgenaxis-desktop/crates/sgenaxis-ports/src/file_commit.rs']:
 p['sources'][q.relative_to(R).as_posix()]=hashlib.sha256(q.read_bytes()).hexdigest()
(O/'audit.json').write_text(json.dumps(p,ensure_ascii=False,indent=2),encoding='utf-8')
body='<h1>8 Yellow dispatch gates</h1><p>AUTHOR GOVERNANCE AUDIT ONLY. Independent acceptance/product/native/build/RED NOT RUN. 796 source hashes match; current HEAD '+p['head']+' differs from historical inventory '+p['historical_inventory_head']+'.</p><p>No blanket stop: each blocked action and its exact gate is separate. Accepted S1/IO are preserved.</p><table border="1"><tr><th>Card</th><th>Product action gate</th><th>Other action readiness</th><th>Candidate hash / review</th></tr>'
for r in p['actions']:
 body+='<tr><td>'+r['card']+'</td><td>'+html.escape(r['missing_gate'])+'</td><td>'+html.escape(r['authorized_preparation'])+'</td><td>'
 if r.get('candidate'): body+='<a href="'+os.path.relpath(R/r['candidate'],O).replace('\\','/')+'">Exact candidate</a><br>'+r['candidate_sha256']+'<br>'
 if r.get('review'): body+='<a href="'+os.path.relpath(R/r['review'],O).replace('\\','/')+'">Accepted bounded document review</a>'
 body+='</td></tr>'
body+='</table><h2>Smallest concrete next action</h2><pre>'+html.escape(json.dumps(p['next_dispatch'],ensure_ascii=False,indent=2))+'</pre><h2>Gray candidates inspected</h2><pre>'+html.escape(json.dumps(p['gray_fallback'],ensure_ascii=False,indent=2))+'</pre><h2>Other independent decisions</h2><pre>'+html.escape(json.dumps(p['owner_dependency_order'],ensure_ascii=False,indent=2))+'</pre>'
(O/'index.html').write_text('<!doctype html><html><meta charset="utf-8"><title>Yellow dispatch gates audit</title><style>body{font:15px system-ui;margin:2rem}td{padding:1rem;vertical-align:top}pre{white-space:pre-wrap}</style>'+body+'<script type="application/json" id="module-spec">'+json.dumps(p,ensure_ascii=False).replace('</','<\\/')+'</script></html>',encoding='utf-8')
